	public function verificaPrilegioCerrar($subserie_id , $unidaddocumental_id,$currentForm="")
	{
		if(!$this->tienePrilegio($currentForm))
		{
			$permiso_expediente = UnidadDocumentalPeer::getPermisoACarpeta($subserie_id,$unidaddocumental_id);
			if($permiso_expediente['todo_expediente'] || $permiso_expediente['solo_visualizacion'] || $permiso_expediente['permiso_pordependencia']){
				return true;
			}else{
				$this->redirect(sfConfig::get('base_simad').'/no_autorizado_cerrar.html');
			}
		}
	}
	
	public function tienePrilegio($currentForm)
	{ 
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');	
		return $this->getUser()->checkPerm($currentForm, $usuariologuiado);		 
	}
  
	public function getPermSubseriePorUserCount($usuario_id,$subserie_id)
	{
		$usuario_conectado = UsuarioPeer::retrieveByPK($usuario_id);
		$dependencia_conectado = $usuario_conectado->getDependenciaId();
		//*****************************************************************************************************************
		$s = new Criteria();
		$s->setDistinct();
		$s->addJoin(SubseriePorUsuarioPeer::SUBSERIE_ID, SubseriePeer::SUBSERIE_ID);
		$s->addJoin(SubseriePeer::SERIE_ID, SeriePeer::SERIE_ID);
		$s->addJoin(SeriePeer::DEPENDENCIA_ID, DependenciaPeer::DEPENDENCIA_ID);
		$s->add(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_id);
		//*****************************************************************************************************************
		$cton0 = $s->getNewCriterion(SubseriePorUsuarioPeer::SUBSERIE_ID, $subserie_id);
		$cton1 = $s->getNewCriterion(DependenciaPeer::DEPENDENCIA_ID,$dependencia_conectado);
		$cton0->addOr($cton1);
		$s->add($cton0);
		//*****************************************************************************************************************
		$count_subseries = SubseriePorUsuarioPeer::doCount($s);
		//*****************************************************************************************************************
		return  $count_subseries;
	}   
  
	public function executeReadFileMetadata()
	{
		$fname = trim($this->getRequestParameter('fname')) ? trim($this->getRequestParameter('fname')) : null;
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		//*****************************************************************************************************************
		if(empty($fname)){
			$response_info['status'] = 400;
			$response_info['message'] = "Ocurrio un error, los parametros enviados no son validos";
			$this->getResponse()->setContentType('application/json');
			return $this->renderText(json_encode($response_info));
		}
		//*****************************************************************************************************************
		$dirRaiz = ParametroPeer::retrieveByPk(17)->getValortexto();
		$dirTemp = ParametroPeer::retrieveByPk(65)->getValortexto();
		//*****************************************************************************************************************
		$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
		$entidad_text = $usuario->getRegional()->getEntidad()->getDirectorioName();
		$path = $dirRaiz.$entidad_text.DIRECTORY_SEPARATOR.$dirTemp.DIRECTORY_SEPARATOR;
		$directorio = realpath(simad_util::createPath($path));
		//*****************************************************************************************************************
		$fullpath = $directorio.DIRECTORY_SEPARATOR.$fname;
		if(!file_exists($fullpath)){
			$response_info['status'] = 400;
			$response_info['message'] = "Ocurrio un error, el archivo no existe";
			$this->getResponse()->setContentType('application/json');
			return $this->renderText(json_encode($response_info));
		}
		//*****************************************************************************************************************
		$file_metadato = new FileMetaInfo();
		$total_pages = $file_metadato->countPagesWithExifTool($fullpath);
		//*****************************************************************************************************************
		$response_info['status'] = 200;
		$response_info['message'] = "La informaciòn del archivo fue leida exitosamente";
		$response_info['total_pages'] = $total_pages;
		//*****************************************************************************************************************
		$this->getResponse()->setContentType('application/json');
		return $this->renderText(json_encode($response_info));
	}

