		// Función recursiva para construir el árbol jerárquico
		function buildTree($elements, $parentId = null)
		{
			$branch = [];
			foreach ($elements as $element) 
			{
				if ($element['parent_id'] == $parentId) 
				{
					// identificar si es folder y si tiene documento asociado
					$isFolder = !empty($element['filetree_nombre']);
					$hasDocs  = !empty($element['contenidounidaddocumental_id']);

					// Crear nodo base (sin 'data' aún)
					$node = [
						'id' => 'node_' . $element['id'],
						'contenidounidaddocumental_id' => $hasDocs ? $element['contenidounidaddocumental_id'] : null,
						'label' => $element['filetree_nombre'] ?: $element['descripcion'],
						// Por defecto suponemos carpeta; ajustaremos más abajo
						'inode' => true,
						'open' => false,
						'icon' => $isFolder ? 'folder' : 'file',
						'type' => $isFolder ? 'folder' : 'file',
						'props' => [
							'contenidounidaddocumental_id' => $hasDocs ? $element['contenidounidaddocumental_id'] : null,
							'tipo_doc' => $element['tipo_doc'],
							'descripcion' => $element['descripcion'],
							'folio_inicial' => $element['folio_inicial'],
							'folio_final' => $element['folio_final'],
							'fecha_documento' => $element['fecha_doc'],
							'origen' => $element['origen'],
							'filetree_desc' => $element['filetree_desc'],
						],
					];

					// Si hay documento asociado, agregamos 'data' (esto permitirá que attachDocumentsRecursively genere el subnodo documento)
					if ($hasDocs) {
						$node['data'] = [
							'tipo_doc' => $element['tipo_doc'],
							'descripcion' => $element['descripcion'],
							'folio_inicial' => $element['folio_inicial'],
							'folio_final' => $element['folio_final'],
							'fecha_documento' => $element['fecha_doc'],
							'origen' => $element['origen'],
							'filetree_desc' => $element['filetree_desc'],
						];
					}

					$children = [];
					if ($element['contenidodocfiletree_id']) {
						// Hijos del nodo (si los hay)
						$children = buildTree($elements, $element['contenidodocfiletree_id']);
					}

					if (!empty($children)) {
						$node['branch'] = $children;
					}

					// Si es folder y NO tiene hijos y NO tiene documentos -> marcar inode=false para evitar placeholder
					if ($isFolder && empty($children) && !$hasDocs) {
						$node['inode'] = false;
					} else {
						// para todos los demás casos (carpetas con hijos, carpetas con doc, archivos) mantener inode según su naturaleza
						if ($isFolder) {
							$node['inode'] = true;
							$node['type'] = 'folder';
							$node['icon'] = 'folder';
						} else {
							$node['inode'] = false;
							$node['type'] = 'file';
							$node['icon'] = 'file';
						}
					}

					// Agregar al árbol final
					$branch[] = $node;
				}
			}
			return $branch;
		}


		// Construimos el árbol completo
		$tree = buildTree($items);

		// Procesa recursivamente el árbol para anidar los documentos correctamente
		$tree = $this->attachDocumentsRecursively($tree);

		// Retornamos el JSON que aciTree espera
		$this->getResponse()->setContentType('application/json');
		return $this->renderText(json_encode($tree));
	}

	private function attachDocumentsRecursively(array $nodes)
	{
			foreach ($nodes as &$node) {

				// Si es carpeta vacía, la saltamos
				if (isset($node['__is_empty_folder']) && $node['__is_empty_folder'] === true) {
					continue;
				}


			// Si el nodo tiene hijos, procesarlos recursivamente
			if (isset($node['branch']) && is_array($node['branch'])) {
				$node['branch'] = $this->attachDocumentsRecursively($node['branch']);
			}else if($node['inode'] === false && $node['type'] === 'file'){
				continue;
			}
			//***********************************************************************************
			// Si tiene 'data', significa que contiene un documento asociado
			if (isset($node['data']) && is_array($node['data'])) {
				// Creamos un label descriptivo para el documento
				$tipo  = isset($node['data']['tipo_doc']) ? trim($node['data']['tipo_doc']) : '';
				$desc  = isset($node['data']['descripcion']) ? trim($node['data']['descripcion']) : '';
				$fecha = isset($node['data']['fecha_documento']) ? trim($node['data']['fecha_documento']) : '';
				//*******************************************************************************
				$labelDoc = $tipo;
				if ($desc !== '')  $labelDoc .= ' - ' . $desc;
				if ($fecha !== '') $labelDoc .= ' (' . $fecha . ')';
				$labelDoc = trim($labelDoc);
				//*******************************************************************************

				// Creamos el subnodo (documento)
				$docNode = [
					'id'    => $node['id'] . '_doc',
						'contenidounidaddocumental_id' => $node['contenidounidaddocumental_id'],
					'label' => $labelDoc,
					'inode' => false,
					'open'  => false,
					'icon'  => 'file',
					'type'  => 'file',
					'data'  => $node['data'],
					// NUEVO: props para columnas
					'props' => [
							'contenidounidaddocumental_id' => isset($node['contenidounidaddocumental_id']) ? $node['contenidounidaddocumental_id'] : (isset($node['contenidounidaddocumental_id']) ? $node['contenidounidaddocumental_id'] : ''),
						'tipo_doc' => isset($node['data']['tipo_documental']) ? $node['data']['tipo_documental'] : (isset($node['data']['tipo_documental']) ? $node['data']['tipo_documental'] : ''),
						'folio_inicial' => isset($node['data']['folio_inicial']) ? $node['data']['folio_inicial'] : '',
						'folio_final' => isset($node['data']['folio_final']) ? $node['data']['folio_final'] : '',
						'origen' => isset($node['data']['origen']) ? $node['data']['origen'] : '',
					],
				];
				//*******************************************************************************
				// Configuramos el nodo principal como folder
				$node['inode'] = true;
				$node['open']  = false;
				$node['icon']  = 'folder';
				$node['type']  = 'folder';
				//*******************************************************************************
				// Anidamos el documento como hijo
				if (!isset($node['branch'])) {
					$node['branch'] = [];
				}
				//*******************************************************************************
				$node['branch'][] = $docNode;
				//*******************************************************************************
				// Eliminamos la data del folder (ya se pasó al hijo)
				unset($node['data']);
			}
		}

		unset($node); // buena práctica
		return $nodes;
	}

	public function executeShowFileTree()
	{
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$this->contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('contenidounidaddocumental_id'));
		//*************************************************************************************************************
		$unidaddocumental_id = $this->contenido_unidad_documental->getUnidaddocumentalId();
		$this->contador_unidad_documental = null;
		$this->toda_unidad_documental = null;
		$this->detalles_prestamo = null;
		$this->contador = null;
		$localizacion = $this->contenido_unidad_documental->getUnidadDocumental()->getLocalizacionunidaddocumentalId();
		//*************************************************************************************************************
		if($this->contenido_unidad_documental->getUnidadDocumental()->getEstadotransferencia() == 0){
			$this->contador_unidad_documental = ContenidoUnidadDocumentalPeer::getCountSolicitudes($unidaddocumental_id,$usuariologuiado);
			$this->toda_unidad_documental = ContenidoUnidadDocumentalPeer::getCountPrestamo($unidaddocumental_id);
			$this->contador = ContenidoUnidadDocumentalPeer::getCountSolicitudesPorContenido($this->contenido_unidad_documental->getPrimaryKey(),$usuariologuiado);
			//*********************************************************************************************************
			if($localizacion != 1){
				$this->detalles_prestamo = ContenidoUnidadDocumentalPeer::getDetallePrestamoPorContenido($this->contenido_unidad_documental->getPrimaryKey());
			}
		}
		//*************************************************************************************************************
		$this->forward404Unless($this->contenido_unidad_documental);
	}

	public function executeList()
	{
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		//*****************************************************************************************************************
		$c = new Criteria();
		$parametros_consulta = "";
		$unidaddocumental_id = trim($this->getRequestParameter('unidaddocumental_id'));
		$parametros_consulta .= "&unidaddocumental_id=".$unidaddocumental_id;
		//*****************************************************************************************************************
		$unidad_documental = UnidadDocumentalPeer::retrieveByPk($unidaddocumental_id);
		//*****************************************************************************************************************
		if ($unidad_documental == null && !($unidad_documental instanceof UnidadDocumental)) {
			$this->redirect(sfConfig::get('base_simad').'/no_autorizado_cerrar.html');
		}
		//******************VERIFICA PRIVILEGIO PARA ACCESO A LAS IMAGENES POR EXPEDIENTE**********************************
		if ($unidad_documental->getLocalizacionunidaddocumentalId() != 1) {
			$this->verificaPrilegioCerrar($unidad_documental->getSubserieId(),$unidad_documental->getPrimaryKey(),"VER_TODAS_LAS_SUBSERIES");    
		}else{
			$this->getPermSubseriePorUserCount($usuariologuiado, $unidad_documental->getSubserieId());
		}
		//*****************************************************************************************************************
		$subserie = SubseriePeer::retrieveByPk($unidad_documental->getSubserieId());
		$this->tipodocsview_descripcion = $subserie->getTipodocsview()->getDescripcion();
		//*****************************************************************************************************************
		if($subserie->getTipodocsviewId() == 2) // lista carpetas
		{
			$this->redirect('contenido_documental/listFolderTree?unidaddocumental_id='.$unidad_documental->getPrimaryKey());
		}
		//*****************************************************************************************************************
		$this->unidad_documental_estado = $unidad_documental->getEstadounidaddocumental()->getDescripcion();
		//*****************************************************************************************************************
		if ($unidad_documental->getEstadounidaddocumentalId() == 4) {
			$this->getUser()->setFlash('warning', $this->unidad_documental_estado);
		}
		//*****************************************************************************************************************
		$localizacionunidaddocumental_id = $unidad_documental->getLocalizacionunidaddocumentalId();
		//*****************************************************************************************************************
		$c->add(ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, $unidad_documental->getPrimaryKey());
		// CONSULTA POR TIPO DOCUMENTAL
		$tipo_documental = trim($this->getRequestParameter('tipo_documental'));
		if($tipo_documental != ""){
			$c->add(ContenidoUnidadDocumentalPeer::TIPODOCUMENTAL_ID, $tipo_documental);
			$parametros_consulta .= "&tipo_documental=".$tipo_documental;		
		}
		//*****************************************************************************************************************
		// CONSULTA DESCRIPCION
		$descripcion = $this->getRequestParameter('descripcion');
		if($descripcion != ""){
			$c->add(ContenidoUnidadDocumentalPeer::DESCRIPCION, '%'.$descripcion.'%', Criteria::LIKE);
			$parametros_consulta .= "&descripcion=".$descripcion;		
		}
		//*****************************************************************************************************************
		// FOLIOS
		$folios = $this->getRequestParameter('folios');
		if($folios != ""){
			$c->add(ContenidoUnidadDocumentalPeer::FOLIOS, $folios);
			$parametros_consulta .= "&folios=".$folios;		
		}
		//*****************************************************************************************************************
		// remision
		$remision = trim($this->getRequestParameter('numRemision'));
		if($remision != ""){
			$c->add(ContenidoUnidadDocumentalPeer::CONTENIDOUNIDADDOCUMENTAL_ID, $remision);
			$parametros_consulta .= "&numRemision=".$remision;		
		}
		//*****************************************************************************************************************
		// ESTADO
		$estado = trim($this->getRequestParameter('estadocontenidounidaddoc_id'));
		if($estado != ""){
			$c->add(ContenidoUnidadDocumentalPeer::ESTADOCONTENIDOUNIDADDOC_ID, $estado);
			$parametros_consulta .= "&estadocontenidounidaddoc_id=".$estado;		
		}
		//*****************************************************************************************************************
		// VERIFICACION
		$verificacion = trim($this->getRequestParameter('verificacioncontunidaddoc_id'));
		if($verificacion != ""){
			$c->add(ContenidoUnidadDocumentalPeer::VERIFICACIONCONTUNIDADDOC_ID, $verificacion);
			$parametros_consulta .= "&verificacioncontunidaddoc_id=".$verificacion;		
		}
		//*****************************************************************************************************************
		// CONSULTA FECHA CREACION
		$fecha_creacion_inicial = $this->getRequestParameter('desde');
		$fecha_creacion_final = $this->getRequestParameter('hasta');
		if($fecha_creacion_inicial != ""){
			if($fecha_creacion_final == ""){
				$fecha_creacion_final = $fecha_creacion_inicial;
			}
			$c->add(ContenidoUnidadDocumentalPeer::FECHA_CREACION, $fecha_creacion_inicial.' 00:00:00', Criteria::GREATER_EQUAL);
			$c->addAnd(ContenidoUnidadDocumentalPeer::FECHA_CREACION, $fecha_creacion_final.' 23:59:59', Criteria::LESS_EQUAL);
			$parametros_consulta .= "&desde=".str_replace("/","-",$fecha_creacion_inicial);
			$parametros_consulta .= "&hasta=".str_replace("/","-",$fecha_creacion_final);		
		}
		//*****************************************************************************************************************
		$estado_inhabilitado = 3;
		$c->add(ContenidoUnidadDocumentalPeer::ESTADOCONTENIDOUNIDADDOC_ID, $estado_inhabilitado, Criteria::NOT_EQUAL);
		$c->addJoin(ContenidoUnidadDocumentalPeer::TIPODOCUMENTAL_ID, TipoDocumentalPeer::TIPODOCUMENTAL_ID);
		//*****************************************************************************************************************
		$c->addAscendingOrderByColumn(ContenidoUnidadDocumentalPeer::FECHA_DOCUMENTO);
		$c->addAscendingOrderByColumn(ContenidoUnidadDocumentalPeer::ORDEN_CONTENIDO);
		$c->addAscendingOrderByColumn(ContenidoUnidadDocumentalPeer::CONTENIDOUNIDADDOCUMENTAL_ID);
		//*****************************************************************************************************************
		$pager=new sfPropelPager('ContenidoUnidadDocumental',20);
		$pager->setCriteria($c);
		$pager->setPage($this->getRequestParameter('page',1));
		$pager->init();
		$this->filtros_consulta = $parametros_consulta;
		$this->pager=$pager;	
		//*****************************************************Subir por lotes********************************************
		$parametroDirFisicaDig = ParametroPeer::retrieveByPk(27);
		$parametroDirApacheDig = ParametroPeer::retrieveByPk(32);
		$parametroFormatoDig   = ParametroPeer::retrieveByPk(31);	
		$dirFisicaDig = $parametroDirFisicaDig->getValortexto();	
		$dirApacheDig = $parametroDirApacheDig->getValortexto();
		$formatoDig = $this->formatoDig=$parametroFormatoDig->getValortexto();
		$fileExiste = 0;	
		$this->fileExiste = 1;
		//*****************************************************************************************************************
		$contador = array();
		$solicitud_prestamo = array();	
		//****************************Verificar solicitudes del usuario Para Toda La Unidad Documental*********************
		$tu = new Criteria();
		$tu->add(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID,$unidad_documental->getPrimaryKey());
		$tu->add(SolicitudPrestamoPeer::SOLICITUDPRESTAMOESTADO_ID,1);
		$tu->add(SolicitudPrestamoPeer::CONTENIDOUNIDADDOCUMENTAL_ID,NULL);
		$tu->add(SolicitudPrestamoPeer::USUARIO_ID,$usuariologuiado);
		$this->contador_unidad_documental  = SolicitudPrestamoPeer::doCount($tu);
		//*****************************************************************************************************************
		$pru = new Criteria();
		$pru->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID,SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);	
		$pru->add(DetallePrestamoPeer::ESTADOPRESTAMO_ID,1);	
		$pru->add(SolicitudPrestamoPeer::CONTENIDOUNIDADDOCUMENTAL_ID,NULL);		
		$pru->add(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID,$unidad_documental->getPrimaryKey());
		$this->toda_unidad_documental = DetallePrestamoPeer::doCount($pru);
		//*****************************************************************************************************************
		$usuariologuieado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$array_solicitudes = array();
		foreach($pager->getResults() as $prestamo_documento){
			$s = new Criteria();
			$s->add(SolicitudPrestamoPeer::CONTENIDOUNIDADDOCUMENTAL_ID,$prestamo_documento->getContenidounidaddocumentalId());
			$s->add(SolicitudPrestamoPeer::SOLICITUDPRESTAMOESTADO_ID,1);
			$s->add(SolicitudPrestamoPeer::USUARIO_ID,$usuariologuieado);
			$contador[]  = SolicitudPrestamoPeer::doCount($s);
			//**************Verificar que el documento no este en gestion y realizar la consulta en prestamos**************
			if($localizacionunidaddocumental_id != 1){
				$dp = new Criteria();
				$dp->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID,SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);	
				$dp->add(DetallePrestamoPeer::ESTADOPRESTAMO_ID,1);	
				$dp->add(SolicitudPrestamoPeer::CONTENIDOUNIDADDOCUMENTAL_ID,$prestamo_documento->getContenidounidaddocumentalId());		
				$temp_solicitud_prestamo = DetallePrestamoPeer::doSelectOne($dp);			 
				if($temp_solicitud_prestamo != null){
					$solicitud_prestamo[] = 1;
					$array_solicitudes[] = $temp_solicitud_prestamo->getPrimaryKey();
				}else{
					$solicitud_prestamo[] = 0;
					$array_solicitudes[]  = 0;
				}									
			}
		}
		//*****************************************************************************************************************
		$this->array_solicitudes = $array_solicitudes;
		$this->solicitud_prestamo = $solicitud_prestamo;
		$this->contador = $contador;
		$this->unidaddocumental_id = $unidad_documental->getPrimaryKey();
		$this->unidad_documental = $unidad_documental;
		$this->localizacionunidaddocumental_id = $localizacionunidaddocumental_id;
		$this->total_folios = ContenidoUnidadDocumentalPeer::addNewTotalFolios($unidad_documental->getPrimaryKey());
		$this->total_folios = $unidad_documental->getFolios();
		$this->estadotransfer = $unidad_documental->getEstadotransferencia();
	}
  
