	public function executeFdiskdelete()
	{
		$contenidounidaddocumental_id = !empty(trim($this->getRequestParameter('contenidounidaddocumental_id'))) ? trim($this->getRequestParameter('contenidounidaddocumental_id')) : null;
		$fname_delete = !empty(trim($this->getRequestParameter('filenameimg'))) ? trim($this->getRequestParameter('filenameimg')) : null;
		//*******************************************************************************************************************
		if(empty($fname_delete)){
			$response_info['status'] = 400;
			$response_info['message'] = "Ocurrio un error, los parametros enviados no son validos";
			$this->getResponse()->setContentType('application/json');
			return $this->renderText(json_encode($response_info));
		}else if(empty($contenidounidaddocumental_id)){
			$response_info['status'] = 200;
			$response_info['message'] = "Actividad realizada satisfactoriamente";
			$this->getResponse()->setContentType('application/json');
			return $this->renderText(json_encode($response_info));
		}
		//*******************************************************************************************************************
		$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($contenidounidaddocumental_id);
		$files = preg_split("/[,]+/",trim($contenido_unidad_documental->getRuta()), -1, PREG_SPLIT_NO_EMPTY);
		$newurl = array();
		//*******************************************************************************************************************
		foreach ($files as $file){
			$name_file = basename($file);
			if($name_file != $fname_delete){
				$newurl[] = $file;
			}
		}
		//*******************************************************************************************************************
		$contenido_unidad_documental->setRuta(implode(",", $newurl));
		$contenido_unidad_documental->save();
		//*******************************************************************************************************************
		$response_info['status'] = 200;
		$response_info['message'] = "Actividad realizada satisfactoriamente";
		$this->getResponse()->setContentType('application/json');
		return $this->renderText(json_encode($response_info));
	}

