	public function executeDeletePageTiff()
	{
		if($this->getRequestParameter('pagina_posicion')){
			/********************************************************************************/
			$dirRaiz = ParametroPeer::retrieveByPk(17);
			$dirTmp  = ParametroPeer::retrieveByPk(65);  		
			/********************************************************************************/
			$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
			$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
			$entidad_text = $usuario->getRegional()->getEntidad()->getDirectorioName();
			//$regional_text = $usuario->getRegional()->getDirectorioName();
			//$entidad_text = $entidad_text.'/'.$regional_text;
			/********************************************************************************/
			$directorio_raiz = $dirRaiz->getValortexto().$entidad_text;
			$directorio_tmp = $directorio_raiz."/".$dirTmp->getValortexto()."/";
			/*******************************************************************************/
			$path_file = ($this->getRequestParameter('path_fileOrigen'));
			$fileOrigen = trim($this->getRequestParameter('fileOrigen'));
			$temp_file_path = $directorio_tmp . $fileOrigen;
			$is_copy_file = copy($path_file,$temp_file_path);
			/*******************************************************************************/
			$numero_pagina = $this->getRequestParameter('pagina_posicion');
			$position = $this->getRequestParameter('pagina_posicion') * (-1);
			/*******************************************************************************/
			$outputfile= '';
			$objExec= new command_exec();
			$batch = $objExec->create_command("tiffcp",  $outputfile, $fileOrigen , $position,$directorio_tmp);
			/********************************************************************************/
			$path_original = '"'.trim($path_file).'"';
			$archivo_temp = str_replace("/","\\",$temp_file_path);
			$mycmd = "MOVE /Y ".$archivo_temp." ".$path_original;
			$last_line = exec($mycmd);//system($mycmd, $retval);
			/********************************************************************************/
			$msg = 'Se ha Eliminado Satisfactoriamente la Imagen Numero '.$numero_pagina.' Del Archivo '.$fileOrigen;
		}else{
			$msg = 'Debe Digitar Un Numero De Pagina Para Eliminar Del Archivo '.trim($this->getRequestParameter('fileOrigen'));
		}	            
		$this->msg = $msg;    
	}
  
	public function executeUploadMezclar()
	{
		if($submit_boton = $_REQUEST["boton"] == 'Adjuntar'){
			
			$position = 1;
			if($this->getRequestParameter('posicion')){
					$position = $this->getRequestParameter('posicion');
			}elseif($this->getRequestParameter('pagina_posicion')){
					$position = $this->getRequestParameter('pagina_posicion');
			}
			//********************************************************************************
			$directorio_raiz = ParametroPeer::retrieveByPk(17)->getValortexto();
			$dirTmp  = ParametroPeer::retrieveByPk(65)->getValortexto(); 
			//********************************************************************************
			$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
			$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
			$entidad_text = $usuario->getRegional()->getEntidad()->getDirectorioName();
			//$regional_text = $usuario->getRegional()->getDirectorioName();
			//$entidad_text = $entidad_text.'/'.$regional_text;		
			//********************************************************************************
			$directorio_temp = $directorio_raiz.$entidad_text."/".$dirTmp."/";
			//********************************************************************************
			if ($this->getRequest()->hasFiles())  	
			{
				$file_vars = pathinfo($this->getRequest()->getFileName('file'));
				$util_simad = new simad_util();
				$file_random = md5( rand( 10000, 99999 ). date("YmdGis") );
				$fileName = $file_random."_".$util_simad->clean_name_file($file_vars);
				$directorio = simad_util::createPath($directorio_temp);        
				$this->getRequest()->moveFile('file', $directorio.'/'.$fileName);
			}
			//********************************************************************************
			$file_origen = $this->getRequestParameter('fileOrigen');
			$path_original = '"'.trim($this->getRequestParameter('path_fileOrigen')).'"';
			//$path_original = '"'.$this->getRequestParameter('path_fileOrigen').'"';		
			$path_temp = str_replace("/","\\",$directorio_temp.$file_origen);
			exec("COPY /Y ".$path_original." ".$path_temp);
			//********************************************************************************
			if(file_exists($path_temp))
			{
				$outputfile = $fileName;//archivo q se va adicionar			
				$objExec= new command_exec();
				$batch = $objExec->create_command("tiffcp",  $outputfile, $file_origen , $position,$directorio_temp,$directorio_temp,$directorio_temp);
				$file_tmp_name  = $directorio_temp.$outputfile;	        
				$mycmd = "MOVE /Y ".$path_temp." ".$path_original;
				if(is_readable($path_temp)){	        	
					$last_line = exec($mycmd);	          	
					$this->fileOrigen = $file_origen;
				}else{
					echo "is_unread";
					$this->fileOrigen = "Error archivo defectuoso";
				}
				if(file_exists($file_tmp_name)) unlink($file_tmp_name);
			}
		}else{
			return $this->forward('contenido_documental', 'deletePageTiff');
		}           
	}
  
	public function executeMezclarImagen()
	{
		/********************************************************************************/
		$dirRaiz = ParametroPeer::retrieveByPk(17);
		$dirTemp = ParametroPeer::retrieveByPk(65);
		$alias_archivo = ParametroPeer::retrieveByPK(32);
		/********************************************************************************/
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
		$entidad_folder = $usuario->getRegional()->getEntidad()->getDirectorioName();
		$regional_folder = $usuario->getRegional()->getDirectorioName();
		$entidad_text = $entidad_folder.'/'.$regional_folder;  	
		/********************************************************************************/
		$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('contenidounidaddocumental_id'));
		$directorio_image = $dirRaiz->getValortexto();
		$directorio_tmp = $dirRaiz->getValortexto().$entidad_folder."/".$dirTemp->getValortexto()."/";
		$directorio_alias = $alias_archivo->getValortexto();
		/********************************************************************************/
		//$directorio_tmp = ParametroPeer::retrieveByPK(64);
		$temp_dir = simad_util::createPath($directorio_tmp);
		$work_dir = simad_util::createPath($directorio_image);
		$pattern = array("\\", "\\\"", "\\\\");
		$replace = array("/", "/", "/");
		$work_dir = str_replace($pattern,$replace,$work_dir);
		$url_files =   utf8_encode($contenido_unidad_documental->getRuta());
		/********************************************************************************/
		$archivos_upload = explode('/',str_replace($directorio_alias,"",$url_files));
		$nombre_file = str_replace(",","",basename($url_files));
		$ruta_file = "";
		/********************************************************************************/
		for($j=0; $j < count($archivos_upload); $j++)
		{
		if($archivos_upload[$j] != "" && str_replace(",","",$archivos_upload[$j]) != $nombre_file)
		{	       
				$ruta_file .=  $archivos_upload[$j]."/";            
		}
		}
		/********************************************************************************/
		$archivo_original = str_replace("/","\\",($work_dir.$ruta_file.$nombre_file));
		$archivo_nuevo = str_replace("/","\\",$temp_dir.$nombre_file);    
		$is_copy_file = copy($archivo_original,$archivo_nuevo);    
		if($is_copy_file)
		{	    
		$objExec3= new command_exec();
		$outputfile3= str_replace(",","",$nombre_file);
		//$tmp=md5($outputfile3);
		//$objExec3->run_command(sfConfig::get('sf_lib_dir')."\exec\\"."tiffsplit  \"$work_dir$outputfile3\" $tmp  ",$work_dir) ;    
		$batch = $objExec3->create_command("tiffcount",  $outputfile3, $outputfile3 ,-65536,$temp_dir);
		$file_img_tmp = $temp_dir.$outputfile3;
		$file_img_count = $temp_dir.$outputfile3 .".count";
		$file_batch_name = $temp_dir.$batch;
		$image_count = file_get_contents($file_img_count,true);
		/********************************************************************************/
		//ELIMINA LOS ARCHIVOS TEMPORALES CREADOS
		if(file_exists($file_img_count)) unlink($file_img_count);
		//if(file_exists($file_batch_name)) unlink($file_batch_name);
		if(file_exists($file_img_tmp)) unlink($file_img_tmp);
		/********************************************************************************/
		$contenido_unidad_documental->setFolios($image_count);
		$contenido_unidad_documental->save();
		$this->numero_paginas = trim($image_count);
		}
		$this->contenido_unidad_documental =$contenido_unidad_documental;
		$this->filename =$outputfile3;
		$this->pathfilename = utf8_encode($archivo_original);
	}
  
  
