			$numero_paginas = $this->getRequestParameter('numero_paginas');
				
			$merge_pdf = new merge_pdf();
			$file_temp = $merge_pdf->create_command('pdftk',$uploadFile,$outputfile,$position,$numero_paginas,$directorio_temp,$directorio_temp);
			
			$error = '';
			unlink($uploadFile);//se elimina el archivo q se adiciono
			if(file_exists($directorio_temp.$file_temp.'.pdf')){
				//rename($directorio_temp.$file_temp.'.pdf',$outputfile);//se renombra el archivo temporal con el nombre original
				//se renombra el archivo temporal con el nombre original
				rename($directorio_temp.$file_temp.'.pdf',$directorio_temp.basename($this->getRequestParameter('fileOrigen')));
				if(file_exists($directorio_temp.basename($this->getRequestParameter('fileOrigen'))))
				{
					unlink($this->getRequestParameter('fileOrigen'));//se elimina el archivo temporal
					rename($directorio_temp.basename($this->getRequestParameter('fileOrigen')),$this->getRequestParameter('fileOrigen'));		   				   		
				}
			}else{
				unlink($directorio_temp.$file_temp.'.pdf');//se elimina el archivo al cual se le va adicionar
				$error = 'Error al tratar De abrir el Archivo';
			}					
				
			$this->fileOrigen = $this->getRequestParameter('fileOrigen');//se envia el nombre del archivo original a la vista
			$this->error = $error;
					
		}elseif($submit_boton = $_REQUEST["boton"] == 'Eliminar'){
			return $this->forward('contenido_documental', 'deletePage');
		} 
	}
  
