	public function executeMezclarPdf()
	{
		/********************************************************************************/
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
		$entidad_text = $usuario->getRegional()->getEntidad()->getDirectorioName();
		$regional_text = $usuario->getRegional()->getDirectorioName();
		$entidad_text = $entidad_text; //.'/'.$regional_text;  	
		/********************************************************************************/
		$dirRaiz = ParametroPeer::retrieveByPk(17)->getValortexto();
		$palias_text = ParametroPeer::retrieveByPk(32)->getValortexto();
		$folder_tmp = ParametroPeer::retrieveByPk(65)->getValortexto();
		$work_dir = $dirRaiz . $entidad_text . "/" . $folder_tmp . "/";
		$path_file = $dirRaiz . $entidad_text . "/" . $regional_text . "/";
		/********************************************************************************/
		$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('contenidounidaddocumental_id'));
		$files = preg_split("/[,]+/",$contenido_unidad_documental->getRuta(), -1, PREG_SPLIT_NO_EMPTY);
		$fileorigen = str_replace($palias_text, $dirRaiz, $files[0]);
		/********************************************************************************/
		$pdf = new merge_pdf();
		$pdf->getNumeroPaginas('"'.$fileorigen.'"',$work_dir."temp.txt",$work_dir);
		
		$vlineas = file($work_dir."temp.txt");
		
		/* Podemos mostrar / trabajar con todas las l�neas:*/
		foreach ($vlineas as $sLinea){
		$tempLinea = explode(":",$sLinea);
			if($tempLinea[0] == "NumberOfPages")
			$numero_paginas = $tempLinea[1];
		}     	
		/*****************************************************/
		unlink($work_dir."temp.txt");
		$this->fileorigen = $fileorigen;
		$this->numero_paginas = $numero_paginas; 
		$this->contenido_unidad_documental = $contenido_unidad_documental;       
	}
  
	public function executeDeleteMarcados()
	{
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$unidaddocumental_id = $this->getRequestParameter('unidaddocumental_id');
		$modulo = trim($this->getRequestParameter('modulo'));
		//**********************************************************************************************
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$unidaddocumental_id = $this->getRequestParameter('unidaddocumental_id');
		$unidad_documental = UnidadDocumentalPeer::retrieveByPK($unidaddocumental_id);
		//**********************************************************************************************
		if(!empty($unidad_documental->getEstaCerrado())){
			$this->getUser()->setFlash('error_expclose', 'El expediente esta cerrado y no se puede modificar');
			return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&modulo='.$modulo);
		}
		//**********************************************************************************************
		if(trim($unidaddocumental_id) && $this->tienePrilegio($modulo."_ELIMINAR_CONTENIDO"))
		{
			$c = new Criteria();
			$c->add(ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,$unidaddocumental_id);
			$c->add(ContenidoUnidadDocumentalPeer::MARCA,$usuariologuiado);  		
			$contenidos_eliminar = ContenidoUnidadDocumentalPeer::doSelect($c);
			foreach ($contenidos_eliminar as $contenido ) 
			{
				$contdoc_anterior = clone $contenido;
				//**************************************************************************************
				if($contenido->getVinculoRegistro()){
					$contenido->setEstadocontenidounidaddocId(3);
					$contenido->setOrdenContenido(($contenido->getOrdenContenido() * -1));
					$contenido->save();
					//**********************************************************************************
					AuditLogPeer::guardarAuditoriaLite("ContenidoUnidadDocumental",$contdoc_anterior,$contenido,ModulesEnable::Archivo,$unidad_documental->getCodigoBarras(),$usuariologuiado);
				}else{
					ContenidoUnidadDocumentalPeer::deleteRegCascada($contenido->getPrimaryKey());
					$contenido->delete();
				}
			}
		}
	}

