			$this->getRequest()->moveFile('file', $directorio.'/'.$cons.'_'.$fileName);
			$this->fileName = $cons.'_'.$fileName; 
		}elseif($files_uploads){
			$this->fileName = $files_uploads;
		}
	}
  
