	public function executeEdit()
	{
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('contenidounidaddocumental_id'));
		$unidad_documental = UnidadDocumentalPeer::retrieveByPK($this->getRequestParameter('unidaddocumental_id'));
		$subserie_id = $unidad_documental->getSubserieId();
		$modulo = trim($this->getRequestParameter('modulo'));
		//*****************************************************************************************************
		if(!empty($unidad_documental->getEstaCerrado())){
			$this->getUser()->setFlash('error_expclose', 'El expediente esta cerrado y no se puede modificar');
			return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&modulo='.$modulo);
		}
		//*****************************************************************************************************
		if($unidad_documental->getEstadotransferencia() == 1){
			$this->getUser()->setFlash('error', 'No puedes editar un documento que esta pendiente por transferir');
			return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.trim($this->getRequestParameter('unidaddocumental_id')).'&modulo='.trim($this->getRequestParameter('modulo')));
		}
		//*****************************************************************************************************
		$c = new Criteria();
		$c->add(TipoDocumentalPeer::SUBSERIE_ID, $subserie_id);
		$c->addAscendingOrderByColumn(TipoDocumentalPeer::DESCRIPCION);
		$this->tipos_documentales = TipoDocumentalPeer::doSelect($c);
		//*****************************************************************************************************
		$this->modulo = $this->getRequestParameter('modulo');
		//*****************************************************************************************************
		if($unidad_documental->getLocalizacionunidaddocumentalId() == 1)
		{
			$this->iseditdata = true;
			$permGestionEditarDataTipo = $this->tienePrilegio($this->modulo."_EDITAR_TIPO_DOCUMENTAL_DATA");    
			if($permGestionEditarDataTipo || $contenido_unidad_documental->getUsuarioId() == $usuariologuiado ){
				$this->iseditdata = false;
			}
		}else{
			$this->iseditdata = false;
		}
		//*****************************************************************************************************
		$this->contenido_unidad_documental = $contenido_unidad_documental;
		$this->unidad_documental = $unidad_documental;
		$this->file_trees = ContenidodocFiletreePeer::getAllFileTree();
		$this->forward404Unless($this->contenido_unidad_documental);
	}
  
	public function executeVerificaCierreExpediente()
	{
		$tipodocumental_id = $this->getRequestParameter('tipodocumental_id');
		$unidaddocumental_id = trim($this->getRequestParameter('unidaddocumental_id')) ?: null;
		$unidad_documental = UnidadDocumentalPeer::retrieveByPk($unidaddocumental_id);
		$tipo_documental = TipoDocumentalPeer::retrieveByPK($tipodocumental_id);
		$cierra_expediente = $tipo_documental != null ? $tipo_documental->getCierraExpediente() : 0;
		$subserie_id = $unidad_documental->getSubserieId();
		//*******************************************************************************************
		if($tipo_documental == null){
			$data_array['status'] = 400;      
			$data_array['mensaje'] = 'Debe seleccionar un tipo documental';
			//***************************************************************************************
			$this->getResponse()->setContentType('application/json');
			$data_json = json_encode($data_array);
			return $this->renderText($data_json);
		}
		//*******************************************************************************************
		if($cierra_expediente == 1)
		{   
			$msg = 'Creando este documento se iniciara el proceso para cerrar el expediente';
			//***************************************************************************************
			$countFaltan_tdObligatorios = TipoDocumentalPeer::getCountTipoDocRequiredFaltantes($subserie_id, $unidaddocumental_id, $tipodocumental_id);
			//***************************************************************************************
			if(!empty($countFaltan_tdObligatorios)){
				$msg = 'El tipo documental seleccionado, cierra el expediente, sin embargo faltan otros documentos obligatorios por crear, el expediente no se puede cerrar';
			}
			//***************************************************************************************
			$data_array['status'] = 200;      
			$data_array['mensaje'] = $msg;
		}else{
			$countFaltan_tdCierraExpediente = TipoDocumentalPeer::getCountTipoDocCloseExpFaltantes($subserie_id, $unidaddocumental_id, $tipodocumental_id);
			//***************************************************************************************
			if(empty($countFaltan_tdCierraExpediente)){
				$countFaltan_tdObligatorios = TipoDocumentalPeer::getCountTipoDocRequiredFaltantes($subserie_id, $unidaddocumental_id, $tipodocumental_id);
				//***********************************************************************************
				if(empty($countFaltan_tdObligatorios)){
					$data_array['status'] = 200;
					$data_array['mensaje'] = 'Una vez creado este documento, se iniciara el proceso para el cierre del expediente';
				}
			}
		}
		//*******************************************************************************************
		$this->getResponse()->setContentType('application/json');
		$data_json = json_encode($data_array);
		return $this->renderText($data_json);
	}


	public function executeUpdate()
	{
		$ruta_archivo = "";
		$usuarioautenticado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$isNewContenido = false;
		//********************************************************************************************************************************
		if (!$this->getRequestParameter('contenidounidaddocumental_id')){
		$contenido_unidad_documental = new ContenidoUnidadDocumental();
		//******************************************************************************************************************************
		$contdoc_anterior = clone $contenido_unidad_documental;
		//******************************************************************************************************************************
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$descripcion_text = $this->getRequestParameter('descripcion');
		$fecha_creacion = date('Y-m-d G:i:s');
		$contenido_unidad_documental->setMarca(0);
		$contenido_unidad_documental->setVinculoRegistro(0);
		$contenido_unidad_documental->setCreadoPorWeb(1);
		$isNewContenido = true;
		} else {
		$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('contenidounidaddocumental_id'));
		$ruta_archivo = trim($contenido_unidad_documental->getRuta());
		$usuariologuiado = $contenido_unidad_documental->getUsuarioId();
		$contdoc_anterior = clone $contenido_unidad_documental;
		//******************************************************************************************************************************
		if(trim($this->getRequestParameter('newdescription'))){
			$descripcion_text = trim($contenido_unidad_documental->getDescripcion()) ? trim($contenido_unidad_documental->getDescripcion()) : "";
			if(trim($this->getRequestParameter('newdescription'))&& $descripcion_text){
				$descripcion_text .= " / ";
			}
			$descripcion_text .= trim($this->getRequestParameter('newdescription')) ? trim($this->getRequestParameter('newdescription')) : "";
		}else{
			$descripcion_text = $this->getRequestParameter('descripcion');
		}
		//******************************************************************************************************************************
		$contdoc_anterior = clone $contenido_unidad_documental;
		//******************************************************************************************************************************
		$fecha_creacion = $contenido_unidad_documental->getFechaCreacion();
		$this->forward404Unless($contenido_unidad_documental);
		}
		//********************************************************************************************************************************
		$tipodocumental_id = trim($this->getRequestParameter('tipodocumental_id')) ? trim($this->getRequestParameter('tipodocumental_id')) : $contenido_unidad_documental->getTipodocumentalId();
		$unidaddocumental_id = trim($this->getRequestParameter('unidaddocumental_id')) ? trim($this->getRequestParameter('unidaddocumental_id')) : null;
		$unidad_documental = UnidadDocumentalPeer::retrieveByPK($unidaddocumental_id);
		$modulo = trim($this->getRequestParameter('modulo')) ?: "";
		$msgerror = array();
		//********************************************************************************************************************************
		if($unidad_documental == null){
			$this->getUser()->setFlash('error_expclose', 'No se puede realizar la actividad, se presento un error al recuperar la informacion del expediente, intente de nuevo');
			return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$unidaddocumental_id.'&modulo='.trim($this->getRequestParameter('modulo')));
		}
		//********************************************************************************************************************************
		if(!empty($unidad_documental->getEstaCerrado())){
			$this->getUser()->setFlash('error_expclose', 'El expediente esta cerrado y no se puede modificar');
			return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&modulo='.trim($this->getRequestParameter('modulo')));
		}
		//********************************************************************************************************************************
		$total_folios = !empty($this->getRequestParameter('folios')) ? trim($this->getRequestParameter('folios')) : 1;
		$folio_inicial = trim($this->getRequestParameter('folio_inicial')) ?: null;
		$folio_final = trim($this->getRequestParameter('folio_final')) ?: null;
		if(empty($folio_inicial)){
			$folio_inicial = ContenidoUnidadDocumentalPeer::getMaxFolioFinalByExpDoc($unidaddocumental_id);
			$folio_final = $folio_inicial + ($total_folios - 1);
		}
		//********************************************************************************************************************************
		$contenido_unidad_documental->setUnidaddocumentalId($unidaddocumental_id);
		$contenido_unidad_documental->setVerificacioncontunidaddocId($this->getRequestParameter('verificacioncontunidaddoc_id') ? $this->getRequestParameter('verificacioncontunidaddoc_id') : $contenido_unidad_documental->getVerificacioncontunidaddocId());
		$contenido_unidad_documental->setTipodocumentalId($tipodocumental_id);
		$contenido_unidad_documental->setEstadocontenidounidaddocId($this->getRequestParameter('estadocontenidounidaddoc_id') ? $this->getRequestParameter('estadocontenidounidaddoc_id') : $contenido_unidad_documental->getEstadocontenidounidaddocId());
		$contenido_unidad_documental->setUsuarioId($usuariologuiado);
		$contenido_unidad_documental->setSoporteunidaddocumentalId($this->getRequestParameter('soporteunidaddocumental_id') ? $this->getRequestParameter('soporteunidaddocumental_id') : $contenido_unidad_documental->getSoporteunidaddocumentalId());
		$contenido_unidad_documental->setOrigendocumentoId($this->getRequestParameter('origendocumento_id') ? $this->getRequestParameter('origendocumento_id') : $contenido_unidad_documental->getOrigendocumentoId());
		$contenido_unidad_documental->setTipofirmadigitalId($this->getRequestParameter('tipofirmadigital_id') ? $this->getRequestParameter('tipofirmadigital_id') : $contenido_unidad_documental->getTipofirmadigitalId());    
		$contenido_unidad_documental->setDescripcion(trim($descripcion_text));
		$contenido_unidad_documental->setFechaCreacion($fecha_creacion);
		$contenido_unidad_documental->setFolios($total_folios);
		$contenido_unidad_documental->setFolioInicial($folio_inicial);
		$contenido_unidad_documental->setFolioFinal($folio_final);
		$contenido_unidad_documental->setFuncEncryp("SHA1");
		//$contenido_unidad_documental->setFolios(($contenido_unidad_documental->getFolioFinal()-($contenido_unidad_documental->getFolioInicial()-1)));
		//*******************************************************************************************************************************
		if(trim($this->getRequestParameter('fecha_documento'))){
			$fecha_documento = trim($this->getRequestParameter('fecha_documento'));
			$contenido_unidad_documental->setFechaDocumento($fecha_documento);
			if($unidad_documental->getFechaCierre() == null){
				$new_vencimiento = $unidad_documental->getFechaVencimientoCustom($fecha_documento);
				$unidad_documental->setFechavencimiento($new_vencimiento);
				$unidad_documental->save();
			}
		}
		//*******************************************************************************************************************************
		$archivos_upload = preg_split("/[,]+/", $this->getRequestParameter('ruta'),-1,PREG_SPLIT_NO_EMPTY);
		$nfiles_process = array();
		//MANEJO DE ARCHIVOS UPLAODS
		if(trim($this->getRequestParameter('ruta'))){
			$archivos_upload = preg_split("/[,]+/", $this->getRequestParameter('ruta'),-1,PREG_SPLIT_NO_EMPTY);
			//*********************RUTA Y ESTRUCTURA DE ARCHIVOS*************************************************************************
			$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
			//***************************************************************************************************************************
			$folder_list = $unidad_documental->getBaseUrlAttachment($usuario->getPrimaryKey(),true);
			//***************************************************************************************************************************
			$directorio_tmp = $folder_list['temp_path'];
			$directorio_entidad = $folder_list['full_path'];
			//$alias_web = $folder_list['alias_web'];
			$path_absolute = $folder_list['absolute_path'];
			$path_relative = $folder_list['basic_path'];
			//***************************************************************************************************************************
			$new_files = array();$szfile = 0;$exfile = null;
			//****************************************************************************************************************************
			foreach($archivos_upload as $file)
			{
				$file_upload = trim($file);
				if($file_upload)
				{
					$file_source = $directorio_tmp.DIRECTORY_SEPARATOR.$file_upload;
					$file_target = ($directorio_entidad).DIRECTORY_SEPARATOR.$file_upload;
					//********************************************************************************************************************
					if(@copy($file_source,$file_target))
					{
						$szfile = filesize($file_source);
						$exfile = pathinfo($file_source, PATHINFO_EXTENSION);
						$new_files[] = $file_upload;
						$nfiles_process[] = $file_target;
						unlink($directorio_tmp.DIRECTORY_SEPARATOR.$file_upload);
					}
					elseif(file_exists($file_target))
					{
						$szfile = filesize($file_target);
						$exfile = pathinfo($file_target, PATHINFO_EXTENSION);
						$new_files[] = $file_upload;
						$path_absolute = $contenido_unidad_documental->getPathAbsolute();
						$path_relative = $contenido_unidad_documental->getPathRelative();
					}
					else
					{
						$new_files = preg_split("/[,]+/",trim($ruta_archivo), -1, PREG_SPLIT_NO_EMPTY);
						$msgerror[] =  "Archivo no encontrado ".$file_upload;
					}
				}
			}
			//***************************************************************************************************************************
			/*if(count($new_files)){
				$strspe = simad_util::endsWith(trim($ruta_archivo),",") ? "" : ",";
				$ruta_archivo = $ruta_archivo.$strspe.implode(",",$new_files);
			}*/
			//***************************************************************************************************************************
			$contenido_unidad_documental->setRuta((count($new_files) ? implode(",",$new_files) : null));
			$contenido_unidad_documental->setSizeFile($szfile);
			$contenido_unidad_documental->setFormatFile(strtoupper($exfile));
			$contenido_unidad_documental->setPathAbsolute($path_absolute);
			$contenido_unidad_documental->setPathRelative($path_relative);
		}
		//*******************************************************************************************************************************
		$contenidodocfiletree_id = trim($this->getRequestParameter('contenidodocfiletree_id')) ? trim($this->getRequestParameter('contenidodocfiletree_id')) : null;
		$contenido_unidad_documental->setContenidodocfiletreeId($contenidodocfiletree_id);
		//*******************************************************************************************************************************	
		$contenido_unidad_documental->save();
		//*******************************************************************************************************************************	
		$orden_documento = ContenidoUnidadDocumentalPeer::getOrderByDocInExp($unidaddocumental_id);
		$contenido_unidad_documental->setOrdenContenido($orden_documento);
		//*******************************************************************************************************************************
		$contenido_unidad_documental->generateValorHuella();
		$contenido_unidad_documental->setSoporteExpedienteByOrigenDoc();
		//*******************************************************************************************************************************
		AuditLogPeer::guardarAuditoriaLite("ContenidoUnidadDocumental",$contdoc_anterior,$contenido_unidad_documental,ModulesEnable::Archivo,$unidad_documental->getCodigoBarras(),$usuarioautenticado);
		//*******************************************************************************************************************************
		$tipodoc_closeexp = $contenido_unidad_documental->getTipoDocumental()->getCierraExpediente();
		$subserie_id = $unidad_documental->getSubserieId();
		//*******************************************************************************************************************************
		$message_info = array();
		$redirect_url = $this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$unidaddocumental_id.'&modulo='.$modulo;
		if(empty($tipodoc_closeexp))  //no cierra el expediente el TD
		{
			//verifica si esta creado el tipo documental de cierre este creado, para proceder con el cierre del expediente
			$countFaltan_tdCierraExpediente = TipoDocumentalPeer::getCountTipoDocCloseExpFaltantes($subserie_id, $unidaddocumental_id, $tipodocumental_id);
			//***************************************************************************************************************************
			if(empty($countFaltan_tdCierraExpediente))
			{
				//verifica si todos los obligatorios estan creados
				$tdNew_esObligatorio = TipoDocumentalPeer::getCountTipoDocRequiredFaltantes($subserie_id, $unidaddocumental_id, $tipodocumental_id);
				//***********************************************************************************************************************
				if(empty($tdNew_esObligatorio)){//todos los obligatorios estan creados
					$respuesta_array = $unidad_documental->cerrarUnidadDocumental($contenido_unidad_documental->getFechaDocumento());
					if($respuesta_array['isError'] == true)
					{
						$this->getUser()->setFlash('error_expclose', $respuesta_array['mensaje']);
					}else{
						$message_info[] = $respuesta_array['mensaje'];
						//$this->getUser()->setFlash('messages_info', $respuesta_array['mensaje']);
					}
				}else{
					$this->getUser()->setFlash('error_expclose', 'El tipo documental que cierra el expediente esta creado, pero hacen falta documentos para completar el expediente, no se puede cerrar el expediente');
				}
			}
			//***************************************************************************************************************************
			if(count($nfiles_process)){
				$response_sign = $contenido_unidad_documental->addFileProcessOcrAndSign($nfiles_process);
				if($response_sign['httpStatus'] == 200){
					$message_info[] = $response_sign['message'];
					//$this->getUser()->setFlash('messages_info', $response_sign['message']);
				}else{
					$this->getUser()->setFlash('messages_error', $response_sign['message']);
				}
			}
			//***************************************************************************************************************************
			if(count($message_info) > 0){
				$this->getUser()->setFlash('messages_info', implode(",",$message_info));
			}
			//***************************************************************************************************************************
			return $this->redirect($redirect_url);
		}
		//*******************************************************************************************************************************
		//verifica si todos los obligatorios estan creados
		$countFaltan_tdObligatorios = TipoDocumentalPeer::getCountTipoDocRequiredFaltantes($subserie_id, $unidaddocumental_id, $tipodocumental_id);
		if(empty($countFaltan_tdObligatorios)){//todos los obligatorios estan creados
			$respuesta_array = $unidad_documental->cerrarUnidadDocumental($contenido_unidad_documental->getFechaDocumento());
			if($respuesta_array['isError'] == true)
			{
				$this->getUser()->setFlash('error_expclose', $respuesta_array['mensaje']);
				//return $this->redirect($redirect_url);
			}else{
				$this->getUser()->setFlash('messages_info', $respuesta_array['mensaje']);
				//return $this->redirect($redirect_url);
			}
		}else{
			$this->getUser()->setFlash('error_expclose', 'El tipo documental seleccionado cierra el expediente, pero hace falta la completitud del expediente, no se puede cerrar el expediente');
			//return $this->redirect($redirect_url);
		}
		//*******************************************************************************************************************************
		if(count($nfiles_process)){
			$response_sign = $contenido_unidad_documental->addFileProcessOcrAndSign($nfiles_process);
			if($response_sign['httpStatus'] == 200){
				$this->getUser()->setFlash('messages_info', $response_sign['message']);
			}else{
				$this->getUser()->setFlash('messages_error', $response_sign['message']);
			}
		}
		//*******************************************************************************************************************************
		return $this->redirect($redirect_url);
	}

