	public function executeUpdateFileTree()
	{
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');

		// validar expresion regular nombre de la carpeta.
		$nombre = $this->getRequestParameter('nombre');
		$regex = '/^[A-Za-z0-9][A-Za-z0-9_\- ]{3,23}[A-Za-z0-9]$/';

			if (!preg_match($regex, $nombre)) {
			$this->getUser()->setFlash('error', 'El nombre no cumple con el formato requerido.');
				return $this->redirect($this->getRequest()->getScriptName() . '/contenido_documental/createFiletree');
			}

			if (!$this->getRequestParameter('unidaddocumental_id')) {
				$this->getUser()->setFlash('error', 'La carpeta a crear debe pertenecer a un expediente.');
				return $this->redirect($this->getRequest()->getScriptName() . '/contenido_documental/createFiletree');
		}

		if (!$this->getRequestParameter('contenidodocfiletree_id')) //modo creacion
		{
			$params = [];
			$params['nombre'] = trim($this->getRequestParameter('nombre')) ? trim($this->getRequestParameter('nombre')) : null;
			$params['descripcion'] = trim($this->getRequestParameter('descripcion')) ? trim($this->getRequestParameter('descripcion')) : null;
			$params['es_actual'] = trim($this->getRequestParameter('es_actual')) ? trim($this->getRequestParameter('es_actual')) : null;
			$params['parent_id'] = trim($this->getRequestParameter('parent_id')) ? trim($this->getRequestParameter('parent_id')) : null;
				$params['unidaddocumental_id'] = trim($this->getRequestParameter('unidaddocumental_id')) ? trim($this->getRequestParameter('unidaddocumental_id')) : null;
			$params['usuario_id'] = $usuariologuiado;

				if ($params['parent_id'] == "" || $params['parent_id'] == 0) {
				$params['parent_id'] = null;
			}

			$file_tree = ContenidodocFiletreePeer::addFileTree($params);

				if ($file_tree == null && $file_tree == array()) {
				$this->getUser()->setFlash('error', 'Nombre no valido, prueba otro nombre');			
					return $this->redirect($this->getRequest()->getScriptName() . '/contenido_documental/createFiletree');
			}
		}
		else  //modo edicion
		{
			$contenidodocfiletree_id = trim($this->getRequestParameter('contenidodocfiletree_id'));
			$obj_file_tree = ContenidodocFiletreePeer::retrieveByPk($contenidodocfiletree_id);

			if($obj_file_tree == null){
				$this->getUser()->setFlash('error', 'No se puede realizar la actividad, se presento un error al recuperar la informacion del expediente, intente de nuevo');
			}

			$params = [];
			$params['nombre'] = trim($this->getRequestParameter('nombre')) ? trim($this->getRequestParameter('nombre')) : null;
			$params['descripcion'] = trim($this->getRequestParameter('descripcion')) ? trim($this->getRequestParameter('descripcion')) : null;
			$params['es_actual'] = trim($this->getRequestParameter('es_actual')) ? trim($this->getRequestParameter('es_actual')) : null;
			$params['parent_id'] = trim($this->getRequestParameter('parent_id')) ? trim($this->getRequestParameter('parent_id')) : null;
				$params['unidaddocumental_id'] = trim($this->getRequestParameter('unidaddocumental_id')) ? trim($this->getRequestParameter('unidaddocumental_id')) : null;
			$params['usuario_id'] = $usuariologuiado;

			$file_tree = ContenidodocFiletreePeer::updateFileTree($params, $obj_file_tree);

				if ($file_tree == null && $file_tree == array()) {
				$this->getUser()->setFlash('error', 'Nombre no valido, prueba otro nombre');
				return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/createFileTree');
			}
		}
	}	

	public function executeViewImage()
	{
		$token = trim($this->getRequestParameter('vtoken'));
		$base_web = sfConfig::get('base_simad');
		$response_process = array('status' => 400, 'message' => 'Error interno del servidor');
		$logfile = sfConfig::get('sf_log_dir').DIRECTORY_SEPARATOR.date('Ymd').'_ErrorAcessImage.log';
		$nlog = false;
		$pkid = trim($this->getRequestParameter('key_id')) ? trim($this->getRequestParameter('key_id')) : null;
		//******************************************************************************************************
		try {
			if(!empty($token)){
				$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($pkid);
				//**********************************************************************************************
				$total_char = strlen($token);
				$offset =  $total_char - 128;
				$parte01 = substr($token,0,64);
				$parte02 = substr($token,(64+$offset),$total_char);
				$token_url = $parte01.$parte02;
				$keytime = substr($token,64,$offset);
				$time = urldecode($keytime);
				$token_base = hash("sha512",$contenido_unidad_documental->getPrimaryKey().$contenido_unidad_documental->getFechaCreacion().$time);
				//**********************************************************************************************
				/*$date_actual = new DateTime(date("Y-m-d G:i:s",time()));
				$date_expiracion = new DateTime(date("Y-m-d G:i:s",$time));
				$date_expiracion->modify('+2 hours');
				//**********************************************************************************************
				$time_expiracion = $date_expiracion->format('Y-m-d G:i:s');
				$time_actual =  $date_actual->format('Y-m-d G:i:s');*/
				//**********************************************************************************************
				$time_actual = strtotime(date("Y-m-d G:i:s",time()));  
				$date_expiracion = strtotime ( "+30 minutes" , strtotime(date("Y-m-d G:i:s",$time)));		
				//**********************************************************************************************
				if($time_actual <= $date_expiracion){
					if($token_url == $token_base){
						$urlfile = preg_split("/[,]+/",trim($contenido_unidad_documental->getRuta()), -1, PREG_SPLIT_NO_EMPTY);
						//**************************************************************************************
						$absolute_path = $contenido_unidad_documental->getPathAbsolute();
						$relative_path = $contenido_unidad_documental->getPathRelative();
						$fullpath = iconv('utf-8', 'cp1252',$absolute_path.DIRECTORY_SEPARATOR.$relative_path.DIRECTORY_SEPARATOR.basename($urlfile[0]));
						$file_source = simad_util::NormalizePath($fullpath);
						$extension = pathinfo($file_source, PATHINFO_EXTENSION);
						//**************************************************************************************
						//este bloque es necesario, porq hay nombres de archivo que utilizan el caracter coma(,)
						//esto hace que el bloque anterior falle al hacer el split
						if(!file_exists($file_source)){
							$urlfile = trim($contenido_unidad_documental->getRuta());
							$fullpath = iconv('utf-8', 'cp1252',$absolute_path.DIRECTORY_SEPARATOR.$relative_path.DIRECTORY_SEPARATOR.basename($urlfile));
							$file_source = simad_util::NormalizePath($fullpath);
							$extension = pathinfo($file_source, PATHINFO_EXTENSION);
						}
						//**************************************************************************************
						$filename = md5(time().uniqid()) .'.'. $extension;
						$tmpfile_path = sfConfig::get('sf_web_dir'). '/tmp/' . $filename;
						//**************************************************************************************
						if(file_exists($file_source)){ 
							//$this->redirect($base_web.'/no_file_exists.html'); 					
							//file_put_contents($tmpfile_path,file_get_contents($file_source));
							//**********************************************************************************
							if(!copy($file_source,$tmpfile_path)){
									if ($nlog) {
										simad_util::writetolog($logfile, "Ocurrio un error con el archivo o este no existe en el servidor: " . $file_source . ' ContenidoDoc: ' . $contenido_unidad_documental->getPrimaryKey());
									}
								$response_process['message'] = 'Ocurrio un error con el archivo o este no existe en el servidor, error al acceder a los archivos de visualización';
							}else{
								$url_viewer = $base_web.'/tmp/'.$filename;
								if(strtolower($extension) == 'pdf'){
									$url_viewer = $base_web.'/viewerEx.php?fileview='.$filename;
								}
								//******************************************************************************
								$response_process = array('status' => 200, 'message' => 'Archivo generado y enviado para visualizacion', 'url_file' => $url_viewer);
							}
							//**********************************************************************************
							//$this->redirect($base_web.'/tmp/'.$filename);
						}else{
								if ($nlog) {
									simad_util::writetolog($logfile, "Archivo no existe path: " . $relative_path . ' ContenidoDoc: ' . $contenido_unidad_documental->getPrimaryKey());
								}
							$response_process['message'] = 'Ocurrio un error con el archivo o este no existe en el servidor';
						}
					}
				}else{
					$response_process['message'] = 'El archivo no puede ser visualizado, actualice la pagina e intente de nuevo';
					//$this->redirect($base_web.'/no_file_exists.html');
				}
			}else{
				$response_process['message'] = 'No tine acceso a este recurso, actualice la pagina e intente de nuevo';
				//$this->redirect($base_web.'/no_file_exists.html');
			}
		} catch (PropelException $th) {
				if ($nlog) {
					simad_util::writetolog($logfile, "Error de acceso a la base de datos: " . $th->getMessage() . ' ContenidoDoc: ' . $pkid);
				}
			$response_process['message'] = $th->getMessage();
		} catch (\Exception $th) {
				if ($nlog) {
					simad_util::writetolog($logfile, "Error de aplicacion: " . $th->getMessage() . ' ContenidoDoc: ' . $pkid);
				}
			$response_process['message'] = $th->getMessage();
		} catch (\Throwable $th) {
				if ($nlog) {
					simad_util::writetolog($logfile, "Error general de la aplicacion: " . $th->getMessage() . ' ContenidoDoc: ' . $pkid);
				}
			$response_process['message'] = $th->getMessage();
		}
		//******************************************************************************************************
		$this->getResponse()->setContentType('application/json');      
		return $this->renderText(json_encode($response_process));
	}

	public function executeViewImageOld()
	{    
		$token = trim($this->getRequestParameter('vtoken'));
		$base_web = sfConfig::get('base_simad');
		//**************************************************************************************************
		if(!empty($token)){
			$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('key_id'));
			//**********************************************************************************************
			$total_char = strlen($token);
			$offset =  $total_char - 128;
			$parte01 = substr($token,0,64);
			$parte02 = substr($token,(64+$offset),$total_char);
			$token_url = $parte01.$parte02;
			$keytime = substr($token,64,$offset);
			$time = urldecode($keytime);
			$token_base = hash("sha512",$contenido_unidad_documental->getPrimaryKey().$contenido_unidad_documental->getFechaCreacion().$time);
			//**********************************************************************************************
			/*$date_actual = new DateTime(date("Y-m-d G:i:s",time()));
			$date_expiracion = new DateTime(date("Y-m-d G:i:s",$time));
			$date_expiracion->modify('+2 hours');
			//**********************************************************************************************
			$time_expiracion = $date_expiracion->format('Y-m-d G:i:s');
			$time_actual =  $date_actual->format('Y-m-d G:i:s');*/
			//**********************************************************************************************
			$time_actual = strtotime(date("Y-m-d G:i:s",time()));  
			$date_expiracion = strtotime ( "+30 minutes" , strtotime(date("Y-m-d G:i:s",$time)));		
			//**********************************************************************************************
			if($time_actual <= $date_expiracion){
				if($token_url == $token_base){
					$urlfile = preg_split("/[,]+/",trim($contenido_unidad_documental->getRuta()), -1, PREG_SPLIT_NO_EMPTY);
					//**************************************************************************************
					$absolute_path = $contenido_unidad_documental->getPathAbsolute();
					$relative_path = $contenido_unidad_documental->getPathRelative();
					$fullpath = iconv('utf-8', 'cp1252',$absolute_path.DIRECTORY_SEPARATOR.$relative_path.DIRECTORY_SEPARATOR.basename($urlfile[0]));
					$file_source = simad_util::NormalizePath($fullpath);
					$extension = pathinfo($file_source, PATHINFO_EXTENSION);
					//**************************************************************************************
					$filename = md5(time().uniqid()) .'.'. $extension;
					$tmpfile_path = sfConfig::get('sf_web_dir'). '/tmp/' . $filename;
					//**************************************************************************************
						if (!file_exists($file_source)) {
							$this->redirect($base_web . '/no_file_exists.html');
						}
					file_put_contents($tmpfile_path,file_get_contents($file_source));
					//**************************************************************************************
					$this->redirect($base_web.'/tmp/'.$filename);
				}
			}else{
				$this->redirect($base_web.'/no_file_exists.html');
			}
		}else{
			$this->redirect($base_web.'/no_file_exists.html');
		}
	}

	private function getCriteriaFilters(Criteria $c)
	{
		$parametros_consulta = "";
		//**********************************************************************************************
		$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
		$entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
		//**********************************************************************************************
		$c->add(UnidadDocumentalPeer::ESTADOUNIDADDOCUMENTAL_ID, 1);
		//CONSULTA CODIGO BARRAS
		$codigo_barras = trim($this->getRequestParameter('codigo_barras'));
		if(!empty($codigo_barras)){
			$c->add(UnidadDocumentalPeer::CODIGO_BARRAS, '%'.$codigo_barras.'%', Criteria::LIKE);
			//$c->add(UnidadDocumentalPeer::CODIGO_BARRAS, $codigo_barras);
			$parametros_consulta .= "&codigo_barras=".$codigo_barras;		
		}
		//**********************************************************************************************
		//CONSULTA CODIGO BARRAS
		$id_expediente = trim($this->getRequestParameter('id_expediente'));
		if(!empty($id_expediente)){
			$c->add(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, $id_expediente);
			$parametros_consulta .= "&id_expediente=".$id_expediente;		
		}
		//**********************************************************************************************
		//CONSULTA TITULO
		$titulo = trim($this->getRequestParameter('titulo'));
		if(!empty($titulo)){
			$c->add(UnidadDocumentalPeer::TITULO, '%'.$titulo.'%', Criteria::LIKE);
			$parametros_consulta .= "&titulo=".$titulo;		
		}
		//**********************************************************************************************
		// CONSULTA CONTENIDO
		$contenido = trim($this->getRequestParameter('contenido'));
		if(!empty($contenido)){
			$cad_contenido = str_replace('|','%',$contenido);
			$c->add(UnidadDocumentalPeer::CONTENIDO, '%'.$cad_contenido.'%', Criteria::LIKE);
			$parametros_consulta .= "&contenido=".$cad_contenido;
		}
		//**********************************************************************************************
		// CONSULTA POR MARCA
		$marca = trim($this->getRequestParameter('marcado'));
		if(!empty($marca)){
			$c->add(UnidadDocumentalPeer::MARCA, $usuario_conectado);
			$parametros_consulta .= "&marcado=".$usuario_conectado;
		}
		//**********************************************************************************************
		//CONSULTA LOCALIZACION
		$localizacion = trim($this->getRequestParameter('localizacionexpediente'));
		$this->modulo = null;
		if(!empty($localizacion)){
			if($localizacion == 1){
				$this->descripcion_destino = "Archivo Gesti&oacute;n";
				$this->modulo = "GESTION";
			}elseif($localizacion == 2){
				$this->descripcion_destino = "Archivo Central";
				$this->modulo = "CENTRAL";
			}elseif($localizacion == 3){
				$this->descripcion_destino = "Archivo Hist&oacute;rico";
				$this->modulo = "HISTORICO";
			}
			//******************************************************************************************
			$c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID, $localizacion);
			$parametros_consulta .= "&localizacionexpediente=".$localizacion;		
		}else{
			$c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID, 0);
			$parametros_consulta .= "&localizacionexpediente=".$localizacion;		
		}
		//**********************************************************************************************
		$c->addAscendingOrderByColumn(UnidadDocumentalPeer::CODIGO_BARRAS);
		$this->filtros_consulta = $parametros_consulta;
		//**********************************************************************************************
		return $c;
	}
  
	public function executeShareContenido()
	{
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('contenidounidaddocumental_id'));
		$unidaddocumental_id = $this->getRequestParameter('unidaddocumental_id');
		$unidad_documental = UnidadDocumentalPeer::retrieveByPK($unidaddocumental_id);
		//*****************************************************************************************************************************************
		if($unidad_documental->getLocalizacionunidaddocumentalId() == 1){
			$modulo = "GESTION";
		}elseif($unidad_documental->getLocalizacionunidaddocumentalId() == 2){
			$modulo = "CENTRAL";
		}elseif($unidad_documental->getLocalizacionunidaddocumentalId() == 3){
			$modulo = "HISTORICO";
		}else{
			$modulo = "(NONE)";
		}
		//*****************************************************************************************************************************************
		$currentFormCompartirTipo   = $modulo."_COMPARTIR_CONTENIDO";
		if(!$this->tienePrilegio($currentFormCompartirTipo)){
			$this->redirect(sfConfig::get('base_simad').'/no_autorizado_cerrar.html');
		}
		//*****************************************************************************************************************************************
		$new_contenido = $contenido_unidad_documental->copy();
		$new_contenido->setUsuarioId($usuariologuiado);
		$new_contenido->setFechaCreacion(date('Y-m-d G:i:s'));
		$new_contenido->setUnidaddocumentalId($unidaddocumental_id);
		$new_contenido->setEsCopia(1);
		//*****************************************************************************************************************************************
		if(empty($contenido_unidad_documental->getParentdocId())){
			$new_contenido->setParentdocId($contenido_unidad_documental->getPrimaryKey());
		}
		//*****************************************************************************************************************************************
		$new_contenido->save();
		//*****************************************************************************************************************************************
		$new_contenido->generateValorHuella();
		//*****************************************************************************************************************************************
		$this->forward404Unless($contenido_unidad_documental);
		//*****************************************************************************************************************************************
		//return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$this->getRequestParameter('unidaddocumental_id').'&modulo='.$this->getRequestParameter('modulo'));
	}
  
	public function executeShareContenidoMark($request)
	{
		$contenidounidaddocumental_id = $this->getRequestParameter('contenidounidaddocumental_id');  	
		if($request->isMethod('post') && trim($contenidounidaddocumental_id)){
			$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
			$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($contenidounidaddocumental_id);        
			$tipo_documental = TipoDocumentalPeer::retrieveByPK($contenido_unidad_documental->getTipodocumentalId());
			//************************************************************************************************************
			$expedientes_list = UnidadDocumentalPeer::doSelect($this->getCriteriaFilters(new Criteria()));
			$shared_files = preg_split("/[,]+/", $contenido_unidad_documental->getRuta(),-1,PREG_SPLIT_NO_EMPTY);
			//************************************************************************************************************
			foreach ($expedientes_list as $unidad_documental) {
				$current_contenido = $this->ExistContenidoDocByShared($unidad_documental,$tipo_documental);
				if($current_contenido == null){
					$this->AddNewContenidoByShared($unidad_documental,$contenido_unidad_documental,$tipo_documental);
				}else{
					$this->AddImageByShared($current_contenido,$shared_files);
				}
			}
			//***********************************************************************************************************
		}
		$this->forward404Unless($contenido_unidad_documental);
	}
  
	private function ExistTipoDocumentalByName($subserie_id,TipoDocumental $tipo_documental)
	{
		$tipodocumental_id = $tipo_documental->getPrimaryKey();
		$tipo_descripcion = $tipo_documental->getDescripcion();
		//**************************************************************************************************
		$c = new Criteria();
		//$c->add(TipoDocumentalPeer::TIPODOCUMENTAL_ID,$tipodocumental_id);
		$c->add(TipoDocumentalPeer::DESCRIPCION,$tipo_descripcion);
		$c->add(TipoDocumentalPeer::SUBSERIE_ID,$subserie_id);
		$tipo_doc = TipoDocumentalPeer::doSelectOne($c);
		//**************************************************************************************************
		if($tipo_doc != null)
		{
			return $tipo_doc->getPrimaryKey();
		}else{
			return 0;
		}
	}
  
	private function CreateTipoDocumentalByShared($subserie_id,TipoDocumental $tipo_documental)
	{
		$tipodocumental_id = $tipo_documental->getPrimaryKey();
		$tipo_descripcion = $tipo_documental->getDescripcion();
		//**************************************************************************************************
		if($subserie_id == $tipo_documental->getSubserieId()){
			return $tipodocumental_id;
		}
		//**************************************************************************************************
		$count_reg = $this->ExistTipoDocumentalByName($subserie_id, $tipo_documental);
		if($count_reg == 0){
			$tipo_doc = $tipo_documental->copy();
			$tipo_doc->setSubserieId($subserie_id);
			$tipo_doc->save();
			return $tipo_doc->getPrimaryKey();
		}else{
			return $count_reg;
		}
	}
  
	private function ExistContenidoDocByShared($unidad_documental,TipoDocumental $tipo_documental)
	{
		$tipodocumental_id = $tipo_documental->getPrimaryKey();//2461
		$subserie_id = $unidad_documental->getSubserieId();//1490
		$unidaddocumental_id = $unidad_documental->getPrimaryKey();//68348
		//**************************************************************************************************
		if($subserie_id != $tipo_documental->getSubserieId())
		{
			$count_reg = $this->ExistTipoDocumentalByName($subserie_id, $tipo_documental);
			if($count_reg == 0)
			{     	
				return null;
			}else{
				$tipodocumental_id = $count_reg;
			}
		}
		//**************************************************************************************************
		$c = new Criteria();
		$c->add(ContenidoUnidadDocumentalPeer::TIPODOCUMENTAL_ID,$tipodocumental_id);
		$c->add(ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,$unidaddocumental_id);
		$c->addDescendingOrderByColumn(ContenidoUnidadDocumentalPeer::FECHA_CREACION);
		$contenido = ContenidoUnidadDocumentalPeer::doSelectOne($c);
		//**************************************************************************************************
		if(!$contenido){
			return null;
		}else{
			return $contenido;
		}
	}
  
	private function AddImageByShared(ContenidoUnidadDocumental $target_contenido,$shared_files)
	{
		$current_files = preg_split("/[,]+/", $target_contenido->getRuta(),-1,PREG_SPLIT_NO_EMPTY);
		$new_files = array_merge($current_files,$shared_files);    
		//***************************************************************************************************
		if($new_files)
		{
			$unique_files = array_unique($new_files);
			$ruta_files = implode(",",$unique_files);
			if(trim($ruta_files))
			{
				$target_contenido->setRuta($ruta_files.',');
				$target_contenido->save();
			}
		}
	}
  
	private function AddNewContenidoByShared(UnidadDocumental $unidad_documental,ContenidoUnidadDocumental $contenido_unidad_documental,
												TipoDocumental $tipo_documental)
	{
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$subserie_id = $unidad_documental->getSubserieId();
		$new_contenido = $contenido_unidad_documental->copy();
		$new_contenido->setUsuarioId($usuariologuiado);
		$new_contenido->setFechaCreacion(date('Y-m-d G:i:s'));
		$new_contenido->setUnidaddocumentalId($unidad_documental->getPrimaryKey());
		$new_contenido->setTipodocumentalId($this->CreateTipoDocumentalByShared($subserie_id,$tipo_documental));
		//**************************************************************************************************
		if($unidad_documental->getFechaCierre() == null){
			$fecha_documento = $contenido_unidad_documental->getFechaDocumento();
			$new_vencimiento = $unidad_documental->getFechaVencimientoCustom($fecha_documento);
			$unidad_documental->setFechavencimiento($new_vencimiento);
			$unidad_documental->save();
		}
		//**************************************************************************************************
		$new_contenido->save();
		$new_contenido->generateValorHuella();
		//**************************************************************************************************
		$new_contenido->setSoporteExpedienteByOrigenDoc();
	}
  
	public function executeDelete()
	{
		$unidaddocumental_id = $this->getRequestParameter('unidaddocumental_id');
		$contenidounidaddocumental_id = $this->getRequestParameter('contenidounidaddocumental_id');
		$modulo = $this->getRequestParameter('modulo');
		$contenido_unidad_documental = ContenidoUnidadDocumentalPeer::retrieveByPk($contenidounidaddocumental_id);
		//**************************************************************************************************
		try {
			if(!$this->tienePrilegio($modulo."_ELIMINAR_CONTENIDO")){
				return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/edit?contenidounidaddocumental_id='.$contenidounidaddocumental_id.'&unidaddocumental_id='.$unidaddocumental_id.'&modulo='.$modulo);
			}
			//**********************************************************************************************
			if($contenido_unidad_documental->getVinculoRegistro()){
				$contenido_unidad_documental->setEstadocontenidounidaddocId(3);
				$contenido_unidad_documental->save();
			}else{
				ContenidoUnidadDocumentalPeer::deleteRegCascada($contenido_unidad_documental->getPrimaryKey());
				$contenido_unidad_documental->delete();
			}
			$this->forward404Unless($contenido_unidad_documental);
			//**********************************************************************************************
			return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$unidaddocumental_id.'&modulo='.$modulo);
		} catch (\Throwable $th) {
			//throw $th;
			return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$unidaddocumental_id.'&modulo='.$modulo);
		}
	}
	
	public function executeTiposDocumentales()
	{
		$cod_mensaje = 0;
		$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');	
		//*****************************************************************************************************
		// CONSULTAMOS LA SUBSERIE DE LA UNIDAD DOCUMENTAL 
		$UniDocumental = UnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('unidaddocumental_id'));	
		$subserie = $UniDocumental->getSubserieId();
		$this->nombre_subserie = $UniDocumental->getSubserie()->getDescripcion();
		//********************************************************************************************************************************
		if(!empty($UniDocumental->getEstaCerrado())){
			$this->getUser()->setFlash('error_expclose', 'El expediente esta cerrado y no se puede modificar');
			return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$UniDocumental->getPrimaryKey().'&modulo='.trim($this->getRequestParameter('modulo')));
		}
		//*****************************************************************************************************
		if($UniDocumental->getEstadotransferencia() == 1){
			$this->getUser()->setFlash('error', 'No puedes adicionar nuevos documentos al expediente, hay una tranferencia pendiente por definir');
			return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.trim($this->getRequestParameter('unidaddocumental_id')).'&modulo='.trim($this->getRequestParameter('modulo')));
		}
		//*****************************************************************************************************
		// CONSULTAMOS LOS TIPOS DOCUMENTALES EXISTENTES PARA ESTA UNIDAD DOCUMENTAL
		$t = new Criteria();
		$t->add(ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, $this->getRequestParameter('unidaddocumental_id'));
		$ActualTiDoc = ContenidoUnidadDocumentalPeer::doSelect($t);
		$tiposDocumentalesExistentes = array();
		foreach($ActualTiDoc as $tipoDocAct){
			$tiposDocumentalesExistentes[] = $tipoDocAct->getTipodocumentalId();
			$cod_mensaje = 1;
		}
		//*****************************************************************************************************
		// CONSULTAMOS LOS TIPOS DOCUMENTALES QUE FALTAN POR CARGAR
		$c = new Criteria();
		$c->add(TipoDocumentalPeer::SUBSERIE_ID, $subserie);
		$c->add(TipoDocumentalPeer::TIPODOCUMENTAL_ID, $tiposDocumentalesExistentes, Criteria::NOT_IN);
		$tiposDocumentales = TipoDocumentalPeer::doSelect($c);
		//*****************************************************************************************************
		foreach($tiposDocumentales as $tipoDocumental){
			$contenido_unidad_documental = new ContenidoUnidadDocumental();
			$contenido_unidad_documental->setUnidaddocumentalId($this->getRequestParameter('unidaddocumental_id'));
			$contenido_unidad_documental->setVerificacioncontunidaddocId(2);
			$contenido_unidad_documental->setTipodocumentalId($tipoDocumental->getTipodocumentalId());
			$contenido_unidad_documental->setEstadocontenidounidaddocId(2);
			$contenido_unidad_documental->setUsuarioId($usuario_conectado);
			$contenido_unidad_documental->setDescripcion('Sin Descripcion');
			$contenido_unidad_documental->setRuta('');
			$contenido_unidad_documental->setFechaCreacion(date('Y-m-d G:i:s'));
			$contenido_unidad_documental->setFolios('');
			$contenido_unidad_documental->setCreadoPorWeb('1');
			$contenido_unidad_documental->save();
			$cod_mensaje=2;
		}
		//*****************************************************************************************************
		if($cod_mensaje == 1){
			$this->mensaje = "No Existen Tipos Documentales Pendientes";
		}elseif($cod_mensaje == 2){
			$this->mensaje = "Se Cargaron los Tipos Documentales Exitosamente.";
		}else{
			$this->mensaje = "No se pueden Cargar los Tipos Documentales.";
		}
		$this->unidad_documental = $UniDocumental;
		//*****************************************************************************************************
		return $this->redirect($this->getRequest()->getScriptName().'/contenido_documental/list?unidaddocumental_id='.$this->getRequestParameter('unidaddocumental_id').'&modulo='.$this->getRequestParameter('modulo'));
	}
  
	public function executeDzFileUpload()
	{    
		$data_array = array();
		//***************************************************************************************
		if (!empty($_FILES))
		{
			$dirRaiz = ParametroPeer::retrieveByPk(17)->getValortexto();
			$dirTemp = ParametroPeer::retrieveByPk(65)->getValortexto();
			//***********************************************************************************
			$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
			$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
			$entidad_text = $usuario->getRegional()->getEntidad()->getDirectorioName();
			//$regional_text = $usuario->getRegional()->getDirectorioName();
			//$entidad_text = $entidad_text.'/'.$regional_text;
			$path = $dirRaiz.$entidad_text.DIRECTORY_SEPARATOR.$dirTemp.DIRECTORY_SEPARATOR;
			$directorio = realpath(simad_util::createPath($path));
			//***********************************************************************************
			// Variables que envía Dropzone
			$uuid      = isset($_POST['dzuuid']) ? $_POST['dzuuid'] : md5(microtime());
			$chunkIdx  = isset($_POST['dzchunkindex']) ? intval($_POST['dzchunkindex']) : 0;
			$totalChunks = isset($_POST['dztotalchunkcount']) ? intval($_POST['dztotalchunkcount']) : 1;
			$originalName = isset($_POST['dzuploadfilename']) ? $_POST['dzuploadfilename'] : $_FILES['file']['name'];
			//***********************************************************************************
			$temp_uploaddir = $directorio . DIRECTORY_SEPARATOR . $uuid;
			if (!is_dir($temp_uploaddir)) mkdir($temp_uploaddir, 0777, true);
			//***********************************************************************************
			// Guardar chunk
			if (!move_uploaded_file($_FILES['file']['tmp_name'], "$temp_uploaddir/$chunkIdx")) {
				header("HTTP/1.1 500 Error guardando trozo");
				exit;
			}
			//***********************************************************************************
			// Si es el último chunk, hacemos el merge
			if ($chunkIdx === $totalChunks - 1) 
			{
				$file_vars = pathinfo($originalName);
				$util_simad = new simad_util();
				$fileName = $util_simad->clean_name_file($file_vars);
				$cons    = ParametroPeer::getNewConsecutivo();
				//*******************************************************************************
				$finalPath = $directorio . DIRECTORY_SEPARATOR . $cons.'_'.$fileName;
				//*******************************************************************************
				$out = fopen($finalPath, 'wb');
				if (!$out) {
					header("HTTP/1.1 500 No se pudo abrir fichero final");
					exit;
				}
				//*******************************************************************************
				// Leer cada trozo en orden
				for ($i = 0; $i < $totalChunks; $i++) 
				{
					$part = "$temp_uploaddir/$i";
					if (!file_exists($part)) {
						header("HTTP/1.1 500 Falta el trozo $i");
						fclose($out);
						exit;
					}
					$in = fopen($part, 'rb');
					stream_copy_to_stream($in, $out);
					fclose($in);
				}
				//*******************************************************************************
				fclose($out);
				//*******************************************************************************
				// Limpiar los trozos temporales
				array_map('unlink', glob("$temp_uploaddir/*"));
				rmdir($temp_uploaddir);
				//*******************************************************************************
				$data_array['name'] = $cons.'_'.$fileName;
				//*******************************************************************************
				$this->getResponse()->setContentType('application/json');
				$data_json = json_encode($data_array);
				return $this->renderText($data_json);
			}
			//***********************************************************************************
			// Respuesta satisfactoria
			http_response_code(200);
			echo json_encode(['status' => 'ok']);
			exit;
		}else{
			$this->getResponse()->setContentType('application/json');
			$data_json = json_encode($data_array);
			return $this->renderText($data_json);
		}
	}
}
